function getIp(req) {
  return req.headers.get("cf-connecting-ip") || (req.headers.get("x-forwarded-for") || "").split(",")[0].trim() || "unknown";
}

export async function onRequest(context) {
  const { request, env } = context;
  const cors = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, X-Admin-Pin"
  };
  if (request.method === "OPTIONS") return new Response(null, { status: 200, headers: cors });

  const ip = getIp(request);
  const now = Date.now();
  const rec = ipAttempts.get(ip) || { failed: 0, lockUntil: null };

  if (rec.lockUntil && now < rec.lockUntil) {
    const retryAfterSeconds = Math.ceil((rec.lockUntil - now) / 1000);
    return new Response(JSON.stringify({
      ok: false,
      lockedOut: true,
      error: "Too many failed PIN attempts. Locked out for 15 minutes.",
      retryAfterSeconds
    }), { status: 429, headers: { "Content-Type": "application/json", "Retry-After": String(retryAfterSeconds), ...cors } });
  }
  if (rec.lockUntil && now >= rec.lockUntil) {
    rec.failed = 0;
    rec.lockUntil = null;
  }

  let submittedPin = request.headers.get("x-admin-pin") || new URL(request.url).searchParams.get("pin") || "";
  if (request.method === "POST") {
    try {
      const body = await request.json();
      if (body && body.pin) submittedPin = String(body.pin).trim();
    } catch {}
  }

  const expectedPin = (env && env.ADMIN_PIN) ? String(env.ADMIN_PIN) : ADMIN_PIN;
  if (!submittedPin || submittedPin !== expectedPin) {
    rec.failed += 1;
    if (rec.failed >= MAX_FAILED) {
      rec.lockUntil = now + LOCKOUT_MS;
      ipAttempts.set(ip, rec);
      return new Response(JSON.stringify({
        ok: false,
        lockedOut: true,
        error: "Maximum failed attempts (5) exceeded. Locked out for 15 minutes.",
        retryAfterSeconds: 900,
        remainingAttempts: 0
      }), { status: 429, headers: { "Content-Type": "application/json", "Retry-After": "900", ...cors } });
    }
    ipAttempts.set(ip, rec);
    const remainingAttempts = MAX_FAILED - rec.failed;
    return new Response(JSON.stringify({
      ok: false,
      error: "Invalid Admin PIN. " + remainingAttempts + " attempt(s) remaining before 15-minute lockout.",
      remainingAttempts
    }), { status: 401, headers: { "Content-Type": "application/json", ...cors } });
  }

  ipAttempts.delete(ip);

  const orders = (Array.isArray(SEED_ORDERS) ? SEED_ORDERS : []).map(o => {
    const ship = o.shipping || {};
    const name = o.name || [ship.first_name, ship.last_name].filter(Boolean).join(" ") || "Customer";
    const email = o.email || ship.email || "customer@bargain-drop.online";
    const phone = ship.phone || o.phone || "+61400000000";
    const total = Number(o.total || 0);
    return {
      id: o.id,
      orderNumber: o.id,
      date: o.date || new Date().toISOString(),
      status: o.status || "paid",
      total,
      currency: "AUD",
      customer: { name, email, phone },
      shipping: {
        fullName: name,
        street1: ship.address1 || "100 George St",
        city: ship.city || "Sydney",
        state: ship.province || "NSW",
        postcode: ship.zip || "2000",
        country: ship.country || "Australia",
        phone
      },
      payment: o.payment || { method: "Credit Card / PayPal", status: "paid" },
      items: Array.isArray(o.items) ? o.items : []
    };
  });

  const records = orders.map(o => ({
    order_id: o.id,
    customer_name: o.customer.name,
    customer_email: o.customer.email,
    customer_phone: o.customer.phone,
    total_amount: Number(o.total.toFixed(2)),
    currency: "AUD",
    status: o.status,
    created_at: o.date,
    shipping_address: o.shipping.street1 + ", " + o.shipping.city + " " + o.shipping.state + " " + o.shipping.postcode
  }));

  const totalRevenue = orders.reduce((s, o) => s + o.total, 0);
  return new Response(JSON.stringify({
    ok: true,
    records,
    orders,
    stats: {
      totalOrders: orders.length,
      totalRevenue: Number(totalRevenue.toFixed(2)),
      paidCount: orders.length,
      unpaidCount: 0,
      shippedCount: 0
    },
    syncedAt: new Date().toISOString()
  }), { status: 200, headers: { "Content-Type": "application/json", ...cors } });
}